/**
 * Base workflow history entry - common fields for all use cases
 */
export interface BaseWorkflowHistoryEntry {
  id: string;
  workflowId: string; // Workflow definition ID
  status: "running" | "completed" | "error" | "cancelled";
  startTime: Date;
  endTime?: Date;
  input: unknown;
  output?: unknown;
}

/**
 * Base workflow step history entry - common fields for all use cases
 */
export interface BaseWorkflowStepHistoryEntry {
  stepIndex: number;
  stepType:
    | "agent"
    | "func"
    | "conditional-when"
    | "parallel-all"
    | "parallel-race"
    | "tap"
    | "workflow"
    | "guardrail"
    | "sleep"
    | "sleep-until"
    | "foreach"
    | "loop"
    | "branch"
    | "map";
  stepName: string;
  status: "pending" | "running" | "completed" | "error" | "skipped"; // includes all possible statuses
  startTime?: Date; // optional since pending steps might not have started
  endTime?: Date;
  input?: unknown;
  output?: unknown;
  agentExecutionId?: string; // Link to agent_history.id if step executes an agent
  parallelIndex?: number; // For parallel steps
}

export interface WorkflowHistoryEntry extends BaseWorkflowHistoryEntry {
  workflowName: string;
  steps: WorkflowStepHistoryEntry[];
  events: WorkflowTimelineEvent[];
  userId?: string;
  conversationId?: string;
  metadata?: Record<string, unknown>;

  createdAt?: Date;
  updatedAt?: Date;
}

/**
 * Used consistently across memory storage and runtime
 */
export interface WorkflowStepHistoryEntry extends BaseWorkflowStepHistoryEntry {
  // Unique identifiers
  id: string;
  stepId?: string;

  workflowHistoryId: string;

  startTime: Date;

  error?: unknown;

  parallelIndex?: number;
  parallelParentStepId?: string;

  agentExecutionId?: string;

  metadata?: Record<string, unknown>;

  createdAt?: Date;
  updatedAt?: Date;
}

/**
 * Workflow timeline event - represents events during workflow execution
 */
export interface WorkflowTimelineEvent {
  id: string;
  workflowHistoryId: string;
  eventId: string;
  name: string;
  type: "workflow" | "workflow-step";
  startTime: string;
  endTime?: string;
  status: string;
  level?: string;
  input?: unknown;
  output?: unknown;
  statusMessage?: unknown;
  metadata?: Record<string, unknown>;
  traceId?: string;
  parentEventId?: string;
  eventSequence?: number;
  createdAt: Date;
}

/**
 * Workflow statistics for reporting
 */
export interface WorkflowStats {
  totalExecutions: number;
  successfulExecutions: number;
  failedExecutions: number;
  averageExecutionTime: number;
  lastExecutionTime?: Date;
}

/**
 * Event emitted during workflow streaming
 */
export type WorkflowStreamEventType =
  | "workflow-start"
  | "workflow-suspended"
  | "workflow-complete"
  | "workflow-cancelled"
  | "workflow-error"
  | "step-start"
  | "step-complete"
  | (string & {});

export interface WorkflowStreamEvent {
  /**
   * Type of the event (e.g., "step-start", "step-complete", "custom", "agent-stream")
   */
  type: WorkflowStreamEventType;
  /**
   * Unique execution ID for this workflow run
   */
  executionId: string;
  /**
   * Source of the event (step ID or name)
   */
  from: string;
  /**
   * Input data for the step/event
   */
  input?: DangerouslyAllowAny;
  /**
   * Output data from the step/event
   */
  output?: DangerouslyAllowAny;
  /**
   * Current status of the step/event
   */
  status: "pending" | "running" | "success" | "skipped" | "error" | "suspended" | "cancelled";
  /**
   * User context passed through the workflow
   */
  context?: UserContext;
  /**
   * Timestamp of the event
   */
  timestamp: string;
  /**
   * Current step index in the workflow
   */
  stepIndex?: number;
  /**
   * Step type for step events
   */
  stepType?:
    | "agent"
    | "func"
    | "conditional-when"
    | "parallel-all"
    | "parallel-race"
    | "tap"
    | "workflow"
    | "guardrail"
    | "sleep"
    | "sleep-until"
    | "foreach"
    | "loop"
    | "branch"
    | "map";
  /**
   * Additional metadata
   */
  metadata?: Record<string, DangerouslyAllowAny>;
  /**
   * Error information if status is "error"
   */
  error?: DangerouslyAllowAny;
}

/**
 * Writer interface for emitting stream events from workflow steps
 */
export interface WorkflowStreamWriter {
  /**
   * Write a custom event to the stream
   */
  write(
    event: Omit<Partial<WorkflowStreamEvent>, "type"> & { type: WorkflowStreamEventType },
  ): void;

  /**
   * Pipe events from an agent's fullStream to the workflow stream
   * @param fullStream - The agent's fullStream async iterable
   * @param options - Optional configuration for piping
   */
  pipeFrom(
    fullStream: AsyncIterable<DangerouslyAllowAny>,
    options?: {
      prefix?: string; // Event type prefix (e.g., "agent-")
      agentId?: string; // Agent ID to include in metadata
      filter?: (part: DangerouslyAllowAny) => boolean; // Optional filter
    },
  ): Promise<void>;
}

/**
 * Response returned from workflow.stream() method
 */
export interface WorkflowStreamResponse<RESULT_SCHEMA extends z.ZodTypeAny> {
  /**
   * Async iterator for stream events
   */
  stream: AsyncIterableIterator<WorkflowStreamEvent>;
  /**
   * Promise that resolves with the final result
   */
  result: Promise<z.infer<RESULT_SCHEMA> | null>;
  /**
   * Workflow execution ID
   */
  executionId: string;
  /**
   * Workflow ID
   */
  workflowId: string;
  /**
   * Abort the stream
   */
  abort: () => void;
}

/**
 * Options for creating workflow execution
 */
export interface CreateWorkflowExecutionOptions {
  userId?: string;
  conversationId?: string;

import type { Span } from "@opentelemetry/api";
import { isFunction } from "@voltagent/internal/utils";
import type {
  InternalAnyWorkflowStep,
  InternalInferWorkflowStepsResult,
  InternalWorkflowFunc,
} from "../internal/types";
import { defaultStepConfig } from "../internal/utils";
import { matchStep } from "./helpers";
import type {
  WorkflowStepParallelAll,
  WorkflowStepParallelAllConfig,
  WorkflowStepParallelDynamicStepsFunc,
} from "./types";

/**
 * Creates a parallel execution step that runs multiple steps simultaneously and waits for all to complete
 *
 * @example
 * ```ts
 * const w = createWorkflow(
 *   andAll({
 *     id: "parallel-fetch",
 *     steps: [
 *       andThen({
 *         id: "fetch-user",
 *         execute: async ({ data }) => {
 *           const userInfo = await fetchUserInfo(data.userId);
 *           return { userInfo };
 *         }
 *       }),
 *       andThen({
 *         id: "fetch-permissions",
 *         execute: async ({ data }) => {
 *           const permissions = await fetchPermissions(data.userId);
 *           return { permissions };
 *         }
 *       }),
 *       andAgent(
 *         ({ data }) => `Generate recommendations for user ${data.userId}`,
 *         agent,
 *         { schema: z.object({ recommendations: z.array(z.string()) }) }
 *       )
 *     ]
 *   }),
 *   andThen({
 *     id: "combine-results",
 *     execute: async ({ data }) => {
 *       // data is now an array: [{ userInfo }, { permissions }, { recommendations }]
 *       return { combined: data.flat() };
 *     }
 *   })
 * );
 * ```
 *
 * @param config - Configuration object with steps array and metadata
 * @returns A workflow step that executes all steps simultaneously and returns their results as an array
 */
export function andAll<
  INPUT,
  DATA,
  RESULT,
  STEPS extends
    | ReadonlyArray<InternalAnyWorkflowStep<INPUT, DATA, RESULT>>
    | WorkflowStepParallelDynamicStepsFunc<INPUT, DATA, RESULT>,
>({ steps: inputSteps, ...config }: WorkflowStepParallelAllConfig<INPUT, DATA, RESULT, STEPS>) {
  type INFERRED_RESULT = STEPS extends ReadonlyArray<InternalAnyWorkflowStep<INPUT, DATA, RESULT>>
    ? InternalInferWorkflowStepsResult<STEPS>
    : STEPS extends WorkflowStepParallelDynamicStepsFunc<INPUT, DATA, RESULT>
      ? InternalInferWorkflowStepsResult<Awaited<ReturnType<STEPS>>>
      : never;

  return {
    ...defaultStepConfig(config),
    type: "parallel-all",
    steps: inputSteps as unknown as InternalAnyWorkflowStep<INPUT, DATA, INFERRED_RESULT>[],
    execute: async (context) => {
      const { data, state } = context;

      // @ts-expect-error - TODO: fix this
      const steps = await getStepsFunc(inputSteps)(context);
      // No workflow context, execute without events
      if (!state.workflowContext) {
        const promises = steps.map((step) =>
          // @ts-expect-error - TODO: fix this
          matchStep(step).execute(context),
        );
        return (await Promise.all(promises)) as unknown as INFERRED_RESULT;
      }

      // Step events removed - now handled by OpenTelemetry spans

      try {
        // Create child spans for parallel execution if traceContext is available
        const traceContext = state.workflowContext?.traceContext;
        const childSpans: Span[] = [];

        if (traceContext) {
          // Create a child span for each parallel step
          steps.forEach((step, index) => {
            const childSpan = traceContext.createStepSpan(
              index,
              "func", // Child steps in parallel-all are typically functions
              step.name || step.id || `Parallel Step ${index + 1}`,
              {
                stepId: step.id,
                parentStepId: config.id,
                parallelIndex: index,
                input: data,
                attributes: {
                  "workflow.step.parallel": true,
                  "workflow.step.parent_type": "parallel-all",
                },
              },
            );
            childSpans.push(childSpan);
          });
        }

        // Each parallel step executes with tracing
        const stepPromises = steps.map(async (step, index) => {
          const startTime = new Date();
          const childSpan = childSpans[index];

          // Step events removed - now handled by OpenTelemetry spans

          const subState = {
            ...state,
            workflowContext: undefined, // ❌ Remove workflow context to prevent individual event publishing
          };

          // Execute within span context if available
          const executeStep = async () => {
            return (
              matchStep(step)
                // @ts-expect-error - TODO: fix this
                .execute({ ...context, state: subState })
            );
          };

          // Return promise with index and timing to track execution times
          return (
            childSpan && traceContext
              ? traceContext.withSpan(childSpan, executeStep)
              : executeStep()
          )
            .then((result) => {
              // End child span successfully if available
              if (childSpan && traceContext) {
                traceContext.endStepSpan(childSpan, "completed", {
                  output: result,
                });
              }
              return {
                result,
                index,
                success: true,
                startTime: startTime.toISOString(),
                endTime: new Date().toISOString(),
              };
            })
            .catch((error) => {
              // End child span with error if available
              if (childSpan && traceContext) {
                traceContext.endStepSpan(childSpan, "error", {
                  error,
                });
              }
              return {
                error,
                index,
                success: false,
                startTime: startTime.toISOString(),
                endTime: new Date().toISOString(),
              };
            });
        });

        // Wait for all steps to complete
        const allStepResults = await Promise.allSettled(stepPromises);

        // Extract results and check for errors
        const results: any[] = [];
        let hasError = false;
        let firstError: any = null;

        for (const promiseResult of allStepResults) {
          if (promiseResult.status === "fulfilled") {
            const stepResult = promiseResult.value as {
              result?: any;
              error?: any;
              index: number;
              success: boolean;
              startTime: string;
              endTime: string;
            };
            if (stepResult.success) {
              results.push(stepResult.result);
            } else {
              hasError = true;
              if (!firstError) {
                firstError = stepResult.error;
              }
              results.push(undefined); // Placeholder for failed step
            }
          } else {
            hasError = true;
            if (!firstError) {
              firstError = promiseResult.reason;
            }
            results.push(undefined); // Placeholder for rejected promise
          }
        }

        // Step events removed - now handled by OpenTelemetry spans

        // If any step failed, throw the first error
        if (hasError) {
          throw firstError;
        }

        const finalResults = results as unknown as INFERRED_RESULT;

        // Step events removed - now handled by OpenTelemetry spans

        return finalResults;
      } catch (error) {
        // Check if this is a suspension, not an error
        if (
          error instanceof Error &&
          (error.message === "WORKFLOW_SUSPENDED" || error.message === "WORKFLOW_CANCELLED")
        ) {
          // For suspension, we don't publish an error event
          // The workflow core will handle publishing the suspend event
          throw error;
        }

        // Step events removed - now handled by OpenTelemetry spans

        throw error;
      }
    },
  } satisfies WorkflowStepParallelAll<INPUT, DATA, INFERRED_RESULT>;
}

function getStepsFunc<
  INPUT,
  DATA,
  RESULT,
  STEPS extends
    | ReadonlyArray<InternalAnyWorkflowStep<INPUT, DATA, RESULT>>
    | WorkflowStepParallelDynamicStepsFunc<INPUT, DATA, RESULT>,
>(
  steps: STEPS,
): InternalWorkflowFunc<INPUT, DATA, InternalAnyWorkflowStep<INPUT, DATA, RESULT>[], any, any> {
  if (isStepsFunction(steps)) {
    return steps;
  }
  return (async () => {
    return steps;
  }) as unknown as InternalWorkflowFunc<
    INPUT,
    DATA,
    InternalAnyWorkflowStep<INPUT, DATA, RESULT>[],
    any,
    any
  >;
}

function isStepsFunction<INPUT, DATA, RESULT>(
  steps:
    | ReadonlyArray<InternalAnyWorkflowStep<INPUT, DATA, RESULT>>
    | WorkflowStepParallelDynamicStepsFunc<INPUT, DATA, RESULT>,
): steps is InternalWorkflowFunc<
  INPUT,
  DATA,
  InternalAnyWorkflowStep<INPUT, DATA, RESULT>[],
  any,
  any
> {
  return isFunction(steps) && !Array.isArray(steps);
}

import type { ModelMessage } from "@ai-sdk/provider-utils";
import { type InferGenerateOutput, Output, type UIMessage } from "ai";
import type { z } from "zod";
import type { Agent, BaseGenerationOptions } from "../../agent/agent";
import { convertUsage } from "../../utils/usage-converter";
import type { InternalWorkflowFunc, WorkflowExecuteContext } from "../internal/types";
import type { WorkflowStepAgent } from "./types";

type OutputSpec = Output.Output<unknown, unknown>;

export type AgentOutputSchema = OutputSpec | z.ZodTypeAny;

export type InferAgentOutput<SCHEMA extends AgentOutputSchema> = SCHEMA extends OutputSpec
  ? InferGenerateOutput<SCHEMA>
  : SCHEMA extends z.ZodTypeAny
    ? z.infer<SCHEMA>
    : never;

export type AgentConfig<SCHEMA extends AgentOutputSchema, INPUT, DATA> = Omit<
  BaseGenerationOptions,
  "output"
> & {
  schema:
    | SCHEMA
    | ((
        context: Omit<WorkflowExecuteContext<INPUT, DATA, any, any>, "suspend" | "writer">,
      ) => SCHEMA | Promise<SCHEMA>);
};

type AgentResultMapper<INPUT, DATA, SCHEMA extends AgentOutputSchema, RESULT> = (
  output: InferAgentOutput<SCHEMA>,
  context: WorkflowExecuteContext<INPUT, DATA, any, any>,
) => Promise<RESULT> | RESULT;

const isOutputSpec = (value: unknown): value is OutputSpec => {
  if (!value || typeof value !== "object") return false;
  const candidate = value as OutputSpec;
  return (
    typeof candidate.parseCompleteOutput === "function" &&
    typeof candidate.parsePartialOutput === "function" &&
    "responseFormat" in candidate
  );
};

/**
 * Creates an agent step for a workflow
 *
 * @example
 * ```ts
 * const w = createWorkflow(
 *   andAgent(
 *     ({ data }) => `Generate a greeting for the user ${data.name}`,
 *     agent,
 *     { schema: z.object({ greeting: z.string() }) }
 *   ),
 *   andThen({
 *     id: "extract-greeting",
 *     execute: async ({ data }) => data.greeting
 *   })
 * );
 * ```
 *
 * @param task - The task (prompt) to execute for the agent, can be a string or a function that returns a string
 * @param agent - The agent to execute the task using `generateText`
 * @param config - The config for the agent (schema/output) `generateText` call
 * @param map - Optional mapper to shape or merge the agent output with existing data
 * @returns A workflow step that executes the agent with the task
 */
export function andAgent<
  INPUT,
  DATA,
  SCHEMA extends AgentOutputSchema,
  RESULT = InferAgentOutput<SCHEMA>,
>(
  task:
    | UIMessage[]
    | ModelMessage[]
    | string
    | InternalWorkflowFunc<INPUT, DATA, UIMessage[] | ModelMessage[] | string, any, any>,
  agent: Agent,
  config: AgentConfig<SCHEMA, INPUT, DATA>,
  map?: AgentResultMapper<INPUT, DATA, SCHEMA, RESULT>,
) {
  return {
    type: "agent",
    id: agent.id,
    name: agent.name || agent.id,
    purpose: agent.purpose ?? null,
    agent,
    execute: async (context) => {
      const { state } = context;
      const { schema, ...restConfig } = config;
      const finalTask = typeof task === "function" ? await task(context) : task;
      const finalSchema = typeof schema === "function" ? await schema(context) : schema;
      const output = isOutputSpec(finalSchema)
        ? finalSchema
        : Output.object({ schema: finalSchema });

      const mapOutput = async (outputValue: InferAgentOutput<SCHEMA>) => {
        if (map) {
          return (await map(outputValue, context)) as RESULT;
        }

        return outputValue as RESULT;
      };

      // Create step context and publish start event
      if (!state.workflowContext) {
        // No workflow context, execute without events
        const result = await agent.generateText(finalTask, {
          ...restConfig,
          context: restConfig.context ?? state.context,
          conversationId: restConfig.conversationId ?? state.conversationId,
          userId: restConfig.userId ?? state.userId,
          // No parentSpan when there's no workflow context
          output,
        });
        // Accumulate usage if available (no workflow context)
        if (result.usage && state.usage) {
          const convertedUsage = convertUsage(result.usage);
          state.usage.promptTokens += convertedUsage?.promptTokens || 0;
          state.usage.completionTokens += convertedUsage?.completionTokens || 0;
          if (typeof state.usage.cachedInputTokens === "number") {
            state.usage.cachedInputTokens += convertedUsage?.cachedInputTokens || 0;
          }
          if (typeof state.usage.reasoningTokens === "number") {
            state.usage.reasoningTokens += convertedUsage?.reasoningTokens || 0;
          }
          state.usage.totalTokens += convertedUsage?.totalTokens || 0;
        }
        return mapOutput(result.output as InferAgentOutput<SCHEMA>);
      }

      // Step start event removed - now handled by OpenTelemetry spans

      try {
        const result = await agent.generateText(finalTask, {
          ...restConfig,
          context: restConfig.context ?? state.context,
          conversationId: restConfig.conversationId ?? state.conversationId,
          userId: restConfig.userId ?? state.userId,
          // Pass the current step span as parent for proper span hierarchy
          parentSpan: state.workflowContext?.currentStepSpan,
          output,
        });

        // Step success event removed - now handled by OpenTelemetry spans

        // Accumulate usage if available
        if (result.usage && state.usage) {
          const convertedUsage = convertUsage(result.usage);
          state.usage.promptTokens += convertedUsage?.promptTokens || 0;
          state.usage.completionTokens += convertedUsage?.completionTokens || 0;
          if (typeof state.usage.cachedInputTokens === "number") {
            state.usage.cachedInputTokens += convertedUsage?.cachedInputTokens || 0;
          }
          if (typeof state.usage.reasoningTokens === "number") {
            state.usage.reasoningTokens += convertedUsage?.reasoningTokens || 0;
          }
          state.usage.totalTokens += convertedUsage?.totalTokens || 0;
        }

        return mapOutput(result.output as InferAgentOutput<SCHEMA>);
      } catch (error) {
        // Check if this is a suspension, not an error
        if (
          error instanceof Error &&
          (error.message === "WORKFLOW_SUSPENDED" || error.message === "WORKFLOW_CANCELLED")
        ) {
          // For suspension, we don't publish an error event
          // The workflow core will handle publishing the suspend event
          throw error;
        }

        // Step error event removed - now handled by OpenTelemetry spans

        throw error;
      }
    },
  } satisfies WorkflowStepAgent<INPUT, DATA, RESULT>;
}

import type { DangerouslyAllowAny } from "@voltagent/internal/types";
import type { WorkflowExecuteContext } from "../internal/types";
import { defaultStepConfig } from "../internal/utils";
import type { WorkflowStepFunc, WorkflowStepFuncConfig } from "./types";

/**
 * Creates an async function step for the workflow
 *
 * @example
 * ```ts
 * const w = createWorkflow(
 *   andThen({
 *     id: "process-data",
 *     execute: async ({ data }) => {
 *       const processed = await someAsyncOperation(data.value);
 *       return { ...data, processed };
 *     }
 *   }),
 *   andThen({
 *     id: "format-result",
 *     execute: async ({ data }) => {
 *       return { result: `Processed: ${data.processed}` };
 *     }
 *   })
 * );
 * ```
 *
 * @param config - Configuration object with execute function and metadata
 * @returns A workflow step that executes the function and returns the result
 */
export function andThen<
  INPUT,
  DATA,
  RESULT,
  SUSPEND_DATA = DangerouslyAllowAny,
  RESUME_DATA = DangerouslyAllowAny,
>({
  execute,
  inputSchema,
  outputSchema,
  suspendSchema,
  resumeSchema,
  ...config
}: WorkflowStepFuncConfig<INPUT, DATA, RESULT, SUSPEND_DATA, RESUME_DATA>) {
  return {
    ...defaultStepConfig(config),
    type: "func",
    inputSchema,
    outputSchema,
    suspendSchema,
    resumeSchema,
    originalExecute: execute, // ✅ Store original function for serialization
    execute: async (context: WorkflowExecuteContext<INPUT, DATA, SUSPEND_DATA, RESUME_DATA>) => {
      const { state } = context;
      // No workflow context, execute without events
      if (!state.workflowContext) {
        return await execute(context);
      }

      // Step events removed - now handled by OpenTelemetry spans

      try {
        const result = await execute(context);

        // Step events removed - now handled by OpenTelemetry spans

        return result;
      } catch (error) {
        // Check if this is a suspension, not an error
        if (
          error instanceof Error &&
          (error.message === "WORKFLOW_SUSPENDED" || error.message === "WORKFLOW_CANCELLED")
        ) {
          // For suspension, we don't publish an error event
          // The workflow core will handle publishing the suspend event
          throw error;
        }

        // Step events removed - now handled by OpenTelemetry spans

        throw error;
      }
    },
  } as WorkflowStepFunc<INPUT, DATA, RESULT, SUSPEND_DATA, RESUME_DATA>;
}

