/**
 * The base input type for the workflow
 * @private - INTERNAL USE ONLY
 */
export type InternalBaseWorkflowInputSchema =
  | z.ZodTypeAny
  | BaseMessage
  | BaseMessage[]
  | UIMessage
  | UIMessage[]
