# VoltAgent Workflow API — Detailed Reference

> Source: `/tmp/voltagent-core/src/workflow/` (cloned from `voltagent/voltagent`, tag `latest: 2.7.4`)

---

## 1. `createWorkflowChain(config)` — The Builder Entry Point

**Source:** `src/workflow/chain.ts` (line 1089)

```ts
export function createWorkflowChain<
  INPUT_SCHEMA extends InternalBaseWorkflowInputSchema,
  RESULT_SCHEMA extends z.ZodTypeAny,
  SUSPEND_SCHEMA extends z.ZodTypeAny = z.ZodAny,
  RESUME_SCHEMA extends z.ZodTypeAny = z.ZodAny,
>(config: WorkflowConfig<INPUT_SCHEMA, RESULT_SCHEMA, SUSPEND_SCHEMA, RESUME_SCHEMA>)
  : WorkflowChain<INPUT_SCHEMA, RESULT_SCHEMA, WorkflowInput<INPUT_SCHEMA>, SUSPEND_SCHEMA, RESUME_SCHEMA>
```

Returns a `WorkflowChain` builder instance. Every chained method (`.andThen()`, `.andAll()`, etc.) mutates the internal steps array and returns `this` (re-cast to the new data type), enabling full TypeScript type inference across the pipeline.

### `WorkflowConfig<INPUT_SCHEMA, RESULT_SCHEMA, SUSPEND_SCHEMA, RESUME_SCHEMA>`

```ts
type WorkflowConfig = {
  id: string;                    // required — unique ID
  name: string;                  // required — human-readable name
  purpose?: string;              // description
  input?: INPUT_SCHEMA;          // z.ZodTypeAny — validates workflow input
  result: RESULT_SCHEMA;         // z.ZodTypeAny — defines result shape
  suspendSchema?: SUSPEND_SCHEMA; // schema for data passed when suspending
  resumeSchema?: RESUME_SCHEMA;  // schema for data passed when resuming
  memory?: Memory;               // Memory instance for state persistence
  hooks?: WorkflowHooks<...>;    // onStart, onStepStart, onStepEnd, onError, onFinish, onEnd
  logger?: Logger;
  observability?: VoltAgentObservability;
  inputGuardrails?: InputGuardrail[];
  outputGuardrails?: OutputGuardrail<any>[];
  guardrailAgent?: Agent;
  retryConfig?: WorkflowRetryConfig;
  checkpointInterval?: number;   // default: 1
  disableCheckpointing?: boolean;
};
```

**Key type helper:**
```ts
type WorkflowInput<INPUT_SCHEMA> =
  IsUnknown<INPUT_SCHEMA> extends true
    ? BaseMessage | BaseMessage[] | UIMessage | UIMessage[] | string
    : INPUT_SCHEMA extends z.ZodTypeAny
      ? z.infer<INPUT_SCHEMA>
      : undefined;
```
When no `input` schema is provided, the workflow accepts plain strings/messages.

---

## 2. `andThen(config)` — Sequential Function Step

**Source:** `src/workflow/steps/and-then.ts`

```ts
function andThen<INPUT, DATA, RESULT, SUSPEND_DATA, RESUME_DATA>(
  config: WorkflowStepFuncConfig<INPUT, DATA, RESULT, SUSPEND_DATA, RESUME_DATA>
): WorkflowStepFunc<INPUT, DATA, RESULT, SUSPEND_DATA, RESUME_DATA>
```

### Config shape (simplified)

```ts
{
  id: string;             // required
  name?: string;
  purpose?: string;
  retries?: number;
  inputSchema?: z.ZodTypeAny;   // override data type for this step
  outputSchema?: z.ZodTypeAny;  // constrain return type
  suspendSchema?: z.ZodTypeAny; // step-level suspend data shape
  resumeSchema?: z.ZodTypeAny;  // step-level resume data shape
  execute: (context: WorkflowExecuteContext<INPUT, DATA, SUSPEND_DATA, RESUME_DATA>) => Promise<RESULT>;
}
```

### `WorkflowExecuteContext` (available inside every `execute`)

```ts
interface WorkflowExecuteContext<INPUT, DATA, SUSPEND_DATA, RESUME_DATA> {
  data: DATA;                    // current pipeline data (output of previous step)
  state: WorkflowStepState<INPUT>; // immutable workflow-level state (userId, conversationId, …)
  workflowState: WorkflowStateStore;   // mutable key/value bag shared by all steps
  setWorkflowState(update: WorkflowStateUpdater): void;
  getStepData(stepId: string): WorkflowStepData | undefined;
  getStepResult<T>(stepId: string): T | null;
  getInitData<T>(): T;           // returns original workflow input
  suspend(reason?: string, suspendData?: SUSPEND_DATA): Promise<never>;
  bail(result?: WORKFLOW_RESULT): never; // early exit with a result
  abort(): never;
  resumeData?: RESUME_DATA;
  retryCount?: number;
  logger: Logger;
  writer: WorkflowStreamWriter;  // emit custom stream events
}
```

### Chain method signature (on `WorkflowChain`)

```ts
andThen<NEW_DATA>(config: {
  execute: (context: WorkflowExecuteContext<...>) => Promise<NEW_DATA>;
  id: string;
  name?: string;
  purpose?: string;
  retries?: number;
  inputSchema?: z.ZodTypeAny;
  outputSchema?: z.ZodTypeAny;
  suspendSchema?: z.ZodTypeAny;
  resumeSchema?: z.ZodTypeAny;
}): WorkflowChain<INPUT_SCHEMA, RESULT_SCHEMA, NEW_DATA, ...>
```

Data type flows through: the return type of `execute` becomes `CURRENT_DATA` for the next step. If `outputSchema` is provided, its inferred type is used. If `inputSchema` is provided, it overrides the incoming `data` type.

### Example

```ts
createWorkflowChain({ id: "wf", name: "Wf", input: z.object({ name: z.string() }), result: z.string() })
  .andThen({
    id: "enrich",
    execute: async ({ data }) => {
      // data: { name: string }
      return { ...data, greeting: `Hello ${data.name}` };
    },
  })
  .andThen({
    id: "finalize",
    execute: async ({ data }) => {
      // data: { name: string; greeting: string }
      return data.greeting;
    },
  });
```

---

## 3. `andAgent(task, agent, config, map?)` — Agent Step

**Source:** `src/workflow/steps/and-agent.ts`

Calls `agent.generateText(task, { output, ...config })` and returns the structured output.

### Standalone function signature

```ts
function andAgent<INPUT, DATA, SCHEMA extends AgentOutputSchema, RESULT = InferAgentOutput<SCHEMA>>(
  task: string | UIMessage[] | ModelMessage[]
       | ((context: WorkflowExecuteContext<INPUT, DATA, ...>) => Promise<string | UIMessage[] | ModelMessage[]>),
  agent: Agent,
  config: AgentConfig<SCHEMA, INPUT, DATA>,
  map?: (output: InferAgentOutput<SCHEMA>, context: WorkflowExecuteContext<INPUT, DATA, ...>) => Promise<RESULT> | RESULT,
): WorkflowStepAgent<INPUT, DATA, RESULT>
```

### `AgentConfig<SCHEMA, INPUT, DATA>`

```ts
type AgentConfig<SCHEMA, INPUT, DATA> = Omit<BaseGenerationOptions, "output"> & {
  schema:
    | SCHEMA
    | ((context: WorkflowExecuteContext<INPUT, DATA, ...>) => SCHEMA | Promise<SCHEMA>);
};
```

`SCHEMA` can be:
- A **Zod schema** (`z.ZodTypeAny`) — wrapped in `Output.object({ schema })`  
- An **AI SDK Output spec** (`Output.array(...)`, `Output.object(...)`, etc.)

### Type helpers

```ts
type AgentOutputSchema = OutputSpec | z.ZodTypeAny;

type InferAgentOutput<SCHEMA extends AgentOutputSchema> =
  SCHEMA extends OutputSpec ? InferGenerateOutput<SCHEMA>
  : SCHEMA extends z.ZodTypeAny ? z.infer<SCHEMA>
  : never;
```

### Chain method overloads

```ts
// Without map: CURRENT_DATA becomes InferAgentOutput<SCHEMA>
andAgent<SCHEMA>(task, agent, config): WorkflowChain<..., InferAgentOutput<SCHEMA>, ...>

// With map: CURRENT_DATA becomes NEW_DATA (whatever the mapper returns)
andAgent<SCHEMA, NEW_DATA>(task, agent, config,
  map: (output: InferAgentOutput<SCHEMA>, context) => NEW_DATA
): WorkflowChain<..., NEW_DATA, ...>
```

### Example

```ts
.andAgent(
  ({ data }) => `Classify this email: ${data.emailBody}`,
  classifierAgent,
  { schema: z.object({ category: z.enum(["support", "sales", "spam"]), confidence: z.number() }) }
)
// next step sees: data: { category: "support"|"sales"|"spam"; confidence: number }

// With map — merge agent output into existing data:
.andAgent(
  ({ data }) => `Classify: ${data.emailBody}`,
  classifierAgent,
  { schema: z.object({ category: z.enum(["support", "sales", "spam"]) }) },
  (output, { data }) => ({ ...data, category: output.category })
)
// next step sees: data: { emailBody: string; category: "support"|"sales"|"spam" }
```

