## 3. `andAgent(task, agent, config, map?)` — Agent Step

**Source:** `src/workflow/steps/and-agent.ts`

Calls `agent.generateText(task, { output, ...config })` and returns the structured output.

### Standalone function signature

```ts
function andAgent<INPUT, DATA, SCHEMA extends AgentOutputSchema, RESULT = InferAgentOutput<SCHEMA>>(
  task: string | UIMessage[] | ModelMessage[]
       | ((context: WorkflowExecuteContext<INPUT, DATA, ...>) => Promise<string | UIMessage[] | ModelMessage[]>),
  agent: Agent,
  config: AgentConfig<SCHEMA, INPUT, DATA>,
  map?: (output: InferAgentOutput<SCHEMA>, context: WorkflowExecuteContext<INPUT, DATA, ...>) => Promise<RESULT> | RESULT,
): WorkflowStepAgent<INPUT, DATA, RESULT>
```

### `AgentConfig<SCHEMA, INPUT, DATA>`

```ts
type AgentConfig<SCHEMA, INPUT, DATA> = Omit<BaseGenerationOptions, "output"> & {
  schema:
    | SCHEMA
    | ((context: WorkflowExecuteContext<INPUT, DATA, ...>) => SCHEMA | Promise<SCHEMA>);
};
```

`SCHEMA` can be:
- A **Zod schema** (`z.ZodTypeAny`) — wrapped in `Output.object({ schema })`  
- An **AI SDK Output spec** (`Output.array(...)`, `Output.object(...)`, etc.)

### Type helpers

```ts
type AgentOutputSchema = OutputSpec | z.ZodTypeAny;

type InferAgentOutput<SCHEMA extends AgentOutputSchema> =
  SCHEMA extends OutputSpec ? InferGenerateOutput<SCHEMA>
  : SCHEMA extends z.ZodTypeAny ? z.infer<SCHEMA>
  : never;
```

### Chain method overloads

```ts
// Without map: CURRENT_DATA becomes InferAgentOutput<SCHEMA>
andAgent<SCHEMA>(task, agent, config): WorkflowChain<..., InferAgentOutput<SCHEMA>, ...>

// With map: CURRENT_DATA becomes NEW_DATA (whatever the mapper returns)
andAgent<SCHEMA, NEW_DATA>(task, agent, config,
  map: (output: InferAgentOutput<SCHEMA>, context) => NEW_DATA
): WorkflowChain<..., NEW_DATA, ...>
```

### Example

```ts
.andAgent(
  ({ data }) => `Classify this email: ${data.emailBody}`,
  classifierAgent,
  { schema: z.object({ category: z.enum(["support", "sales", "spam"]), confidence: z.number() }) }
)
// next step sees: data: { category: "support"|"sales"|"spam"; confidence: number }

// With map — merge agent output into existing data:
.andAgent(
  ({ data }) => `Classify: ${data.emailBody}`,
  classifierAgent,
  { schema: z.object({ category: z.enum(["support", "sales", "spam"]) }) },
  (output, { data }) => ({ ...data, category: output.category })
)
// next step sees: data: { emailBody: string; category: "support"|"sales"|"spam" }
```

