### `.startAsync(input, options?)` — Fire and forget

```ts
async startAsync(
  input: WorkflowInput<INPUT_SCHEMA>,
  options?: WorkflowRunOptions,
): Promise<WorkflowStartAsyncResult>  // { executionId, workflowId, startAt }
```

### `.toWorkflow()` — Get a reusable `Workflow` instance

```ts
public toWorkflow(): Workflow<INPUT_SCHEMA, RESULT_SCHEMA, SUSPEND_SCHEMA, RESUME_SCHEMA>
```

Useful when you want to register with `WorkflowRegistry` or reuse the compiled workflow across multiple calls (avoids re-running `createWorkflow` on each execution).

### `WorkflowRunOptions` (second argument to all execution methods)

```ts
interface WorkflowRunOptions {
  executionId?: string;
  conversationId?: string;
  userId?: string;
  metadata?: Record<string, unknown>;
  context?: UserContext;
  workflowState?: WorkflowStateStore;  // initial shared state
  memory?: Memory;                     // override workflow memory for this run
  suspendController?: WorkflowSuspendController;
  suspensionMode?: "immediate" | "graceful"; // default: "graceful"
  logger?: Logger;
  retryConfig?: WorkflowRetryConfig;
  checkpointInterval?: number;
  disableCheckpointing?: boolean;
  inputGuardrails?: InputGuardrail[];
  outputGuardrails?: OutputGuardrail<any>[];
  guardrailAgent?: Agent;
}
```

---

## 6. All Available Chain Methods

| Method | Purpose | Result data type |
|---|---|---|
| `.andThen(config)` | Sequential custom function | Return type of `execute` |
| `.andAgent(task, agent, config, map?)` | Run an agent | `InferAgentOutput<SCHEMA>` (or mapped) |
| `.andAll({ steps })` | Parallel, wait for ALL | `InternalInferWorkflowStepsResult<STEPS>` (tuple) |
| `.andRace({ steps })` | Parallel, first wins | `InternalInferWorkflowStepsResult<STEPS>[number]` |
| `.andWhen({ condition, step })` | Conditional execution | `NEW_DATA \| CURRENT_DATA` |
| `.andTap(config)` | Side-effect only, data unchanged | `CURRENT_DATA` (unchanged) |
| `.andGuardrail(config)` | Validate/sanitize | `CURRENT_DATA` (unchanged) |
| `.andSleep(config)` | Pause for duration (ms) | `CURRENT_DATA` (unchanged) |
| `.andSleepUntil(config)` | Pause until a `Date` | `CURRENT_DATA` (unchanged) |
| `.andBranch({ branches })` | Run matching branches | `Array<NEW_DATA \| undefined>` |
| `.andForEach({ step, items? })` | Map step over array | `NEW_DATA[]` |
| `.andDoWhile(config)` | Loop while condition true | `NEW_DATA` |
| `.andDoUntil(config)` | Loop until condition true | `NEW_DATA` |
| `.andMap({ map })` | Re-shape data declaratively | `WorkflowStepMapResult<MAP>` |
| `.andWorkflow(workflow)` | Embed another workflow | `NEW_DATA` |
| `.run(input, opts?)` | Execute, await result | `WorkflowExecutionResult` |
| `.stream(input, opts?)` | Execute with streaming | `WorkflowStreamResult` |
| `.startAsync(input, opts?)` | Fire-and-forget | `WorkflowStartAsyncResult` |
| `.toWorkflow()` | Get reusable `Workflow` | `Workflow<...>` |

---

## 7. Complete End-to-End Example

```ts
import { z } from "zod";
import { createWorkflowChain, andThen, andAll, andAgent } from "@voltagent/core";
import { Memory } from "@voltagent/core";

const memory = new Memory({ storage: new InMemoryStorageAdapter() });

// Build the workflow chain
const userWorkflow = createWorkflowChain({
  id: "user-processing",
  name: "User Processing Workflow",
  purpose: "Fetch, enrich and analyze user data",
  input: z.object({ userId: z.string(), userType: z.enum(["admin", "user"]) }),
  result: z.object({ processed: z.boolean(), summary: z.string() }),
  memory,
})
  // Step 1: sequential transform
  .andThen({
    id: "fetch-user",
    execute: async ({ data }) => {
      const userInfo = await fetchUserInfo(data.userId);
      return { ...data, userInfo };
    },
  })
  // Step 2: parallel fetch
  .andAll({
    id: "parallel-enrichment",
    steps: [
      andThen({
        id: "fetch-permissions",
        execute: async ({ data }) => fetchPermissions(data.userId),
      }),
      andThen({
        id: "fetch-activity",
        execute: async ({ data }) => fetchActivity(data.userId),
      }),
    ] as const,
  })
  // Step 3: combine parallel results into flat object
  .andThen({
    id: "merge",
    execute: async ({ data }) => {
      const [permissions, activity] = data;
      return { permissions, activity };
    },
  })
  // Step 4: agent analysis
  .andAgent(
    ({ data }) =>
      `Summarize user activity: ${JSON.stringify(data.activity)} with permissions: ${JSON.stringify(data.permissions)}`,
    analyzerAgent,
    { schema: z.object({ summary: z.string(), riskLevel: z.enum(["low", "medium", "high"]) }) },
    (output, { data }) => ({ ...data, ...output })
  )
  // Step 5: finalize result
  .andThen({
    id: "finalize",
    execute: async ({ data }) => ({
      processed: true,
      summary: `${data.summary} (risk: ${data.riskLevel})`,
    }),
  });

// Execute — three ways:

// 1) Await
const result = await userWorkflow.run({ userId: "u123", userType: "admin" });
console.log(result.status);  // "completed"
console.log(result.result);  // { processed: true, summary: "..." }

// 2) Stream
const streamResult = userWorkflow.stream({ userId: "u123", userType: "admin" });
for await (const event of streamResult) {
  console.log(event.type, event.status);
}
const final = await streamResult.result;

// 3) Register + fire-and-forget
import { WorkflowRegistry } from "@voltagent/core";
WorkflowRegistry.getInstance().registerWorkflow(userWorkflow.toWorkflow());
const { executionId } = await userWorkflow.startAsync({ userId: "u123", userType: "user" });
```

